function showThankYouMessage() {
  // Display the thank-you message
  const thankYouMessage = document.getElementById("thank-you");
  thankYouMessage.style.display = "block"; // Make the message visible
  setTimeout(function () {
    thankYouMessage.style.display = "none"; // Hide the message after 3 seconds
    $("#exampleModalCenter").modal("hide"); // Hide the modal if applicable
  }, 3000);
}

console.log(document.getElementById("reachoutForm"), "test");

document
  .getElementById("reachoutForm")
  .addEventListener("submit", function (event) {
    event.preventDefault(); // Prevent default form submission
    const formData = new FormData(event.target);

    fetch(
      "https://script.google.com/macros/s/AKfycbzz4tpv8cCk-Qcjivb7NpRwvArcyibfKHX0y5jiuPnuZz7DZasA2vtt2qtCsiGmftHI/exec",
      {
        method: "POST",
        body: formData,
      }
    )
      .then((response) => response.json())
      .then((data) => {
        // Display success response message
        document.getElementById("responseMessage").textContent =
          "Form submitted successfully!";
        showThankYouMessage(); // Show thank-you message
      })
      .catch((error) => {
        // Handle errors
        document.getElementById("responseMessage").textContent =
          "An error occurred. Please try again.";
        console.error("Error:", error);
      });
  });
